const FULLSCREEN = true;          // false = show Scriptable's bar with a Done button
const DEFAULT_PATH = '/TASKS.md';

const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Tasks\">\n<meta name=\"theme-color\" content=\"#111318\" media=\"(prefers-color-scheme: dark)\">\n<meta name=\"theme-color\" content=\"#f6f6f8\" media=\"(prefers-color-scheme: light)\">\n<meta name=\"description\" content=\"Swipe through the sections of a Dropbox-hosted TASKS.md, filter by client, check things off and add new ones.\">\n<title>Tasks</title>\n<style>\n  :root {\n    --bg: #f6f6f8;\n    --surface: #ffffff;\n    --surface-2: #eef0f4;\n    --text: #17181c;\n    --muted: #6b7080;\n    --line: #e2e4ea;\n    --accent: #2f6df6;\n    --accent-ink: #ffffff;\n    --danger: #d64545;\n    --check: #22a06b;\n    --tag-1: #6b4fe0;\n    --tag-2: #d9571d;\n    --tag-3: #1e9e6a;\n    --tag-4: #0b7fbf;\n    --tag-5: #c2317a;\n    --tag-6: #8a6d00;\n    --shadow: 0 8px 24px rgba(20, 24, 40, .16);\n    --radius: 14px;\n    --safe-top: env(safe-area-inset-top, 0px);\n    --safe-bottom: env(safe-area-inset-bottom, 0px);\n    color-scheme: light dark;\n  }\n  @media (prefers-color-scheme: dark) {\n    :root:not([data-theme=\"light\"]) {\n      --bg: #111318;\n      --surface: #1a1d24;\n      --surface-2: #232733;\n      --text: #eceef3;\n      --muted: #9aa0b0;\n      --line: #2c3140;\n      --accent: #6d9bff;\n      --accent-ink: #0c1220;\n      --check: #3ccb8a;\n      --tag-1: #a48cff;\n      --tag-2: #ff8a4c;\n      --tag-3: #4fd39a;\n      --tag-4: #55b3ee;\n      --tag-5: #ff7ab8;\n      --tag-6: #e0c04a;\n      --shadow: 0 8px 24px rgba(0, 0, 0, .5);\n    }\n  }\n  :root[data-theme=\"dark\"] {\n    --bg: #111318;\n    --surface: #1a1d24;\n    --surface-2: #232733;\n    --text: #eceef3;\n    --muted: #9aa0b0;\n    --line: #2c3140;\n    --accent: #6d9bff;\n    --accent-ink: #0c1220;\n    --check: #3ccb8a;\n    --tag-1: #a48cff;\n    --tag-2: #ff8a4c;\n    --tag-3: #4fd39a;\n    --tag-4: #55b3ee;\n    --tag-5: #ff7ab8;\n    --tag-6: #e0c04a;\n    --shadow: 0 8px 24px rgba(0, 0, 0, .5);\n  }\n\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n  html, body { height: 100%; margin: 0; }\n  body {\n    background: var(--bg);\n    color: var(--text);\n    font: 16px/1.4 -apple-system, BlinkMacSystemFont, \"SF Pro Text\", \"Inter\", system-ui, sans-serif;\n    overscroll-behavior-y: none;\n    display: flex;\n    flex-direction: column;\n    height: 100dvh;\n  }\n  button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }\n  input, textarea { font: inherit; color: inherit; }\n\n  /* ---- header ---- */\n  header {\n    padding: calc(var(--safe-top) + 10px) 16px 0;\n    background: var(--bg);\n    flex: 0 0 auto;\n  }\n  .titlebar { display: flex; align-items: center; justify-content: space-between; gap: 12px; }\n  .titlebar h1 { font-size: 22px; margin: 0; letter-spacing: -.01em; }\n  .status { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; }\n  .status .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--muted); }\n  .status.ok .dot { background: var(--check); }\n  .status.busy .dot { background: var(--accent); animation: pulse 1s infinite; }\n  .status.err .dot { background: var(--danger); }\n  @keyframes pulse { 50% { opacity: .3; } }\n  .iconbtn {\n    width: 40px; height: 40px; border-radius: 50%;\n    display: grid; place-items: center; color: var(--muted);\n    background: var(--surface-2);\n  }\n  .iconbtn:active { opacity: .7; }\n\n  .tabs {\n    display: flex; gap: 4px; margin-top: 10px;\n    overflow-x: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch;\n  }\n  .tabs::-webkit-scrollbar { display: none; }\n  .tab {\n    flex: 0 0 auto; padding: 8px 12px; border-radius: 10px 10px 0 0;\n    color: var(--muted); font-weight: 600; font-size: 15px; white-space: nowrap;\n    position: relative;\n  }\n  .tab .n { font-weight: 500; font-size: 12px; margin-left: 4px; opacity: .8; }\n  .tab.active { color: var(--text); }\n  .tab.active::after {\n    content: \"\"; position: absolute; left: 12px; right: 12px; bottom: 0;\n    height: 3px; border-radius: 3px 3px 0 0; background: var(--accent);\n  }\n  .tabs-rule { height: 1px; background: var(--line); }\n\n  .chips {\n    display: flex; gap: 8px; padding: 10px 16px;\n    overflow-x: auto; scrollbar-width: none; background: var(--bg);\n  }\n  .chips::-webkit-scrollbar { display: none; }\n  .chip {\n    flex: 0 0 auto; padding: 6px 12px; border-radius: 999px;\n    border: 1.5px solid var(--line); background: var(--surface);\n    font-size: 14px; font-weight: 600; color: var(--muted);\n    display: inline-flex; align-items: center; gap: 6px;\n  }\n  .chip .swatch { width: 8px; height: 8px; border-radius: 50%; background: var(--c, var(--muted)); }\n  .chip .n { font-weight: 500; opacity: .7; }\n  .chip.on { border-color: var(--c, var(--accent)); color: var(--text); background: color-mix(in srgb, var(--c, var(--accent)) 14%, var(--surface)); }\n\n  /* ---- pages ---- */\n  .pages {\n    flex: 1 1 auto; min-height: 0;\n    display: flex; overflow-x: auto; overflow-y: hidden;\n    scroll-snap-type: x mandatory; scrollbar-width: none;\n    -webkit-overflow-scrolling: touch;\n  }\n  .pages::-webkit-scrollbar { display: none; }\n  .page {\n    flex: 0 0 100%; width: 100%; scroll-snap-align: start; scroll-snap-stop: always;\n    overflow-y: auto; padding: 4px 16px calc(var(--safe-bottom) + 96px);\n    -webkit-overflow-scrolling: touch;\n  }\n  .empty { color: var(--muted); text-align: center; padding: 48px 16px; font-size: 15px; }\n  .empty strong { display: block; color: var(--text); font-size: 17px; margin-bottom: 6px; }\n\n  .card {\n    background: var(--surface); border-radius: var(--radius);\n    padding: 12px 12px 12px 10px; margin: 10px 0;\n    box-shadow: 0 1px 0 var(--line);\n  }\n  .card.done { opacity: .6; }\n  .row { display: flex; gap: 10px; align-items: flex-start; }\n  .box {\n    flex: 0 0 auto; width: 26px; height: 26px; margin-top: 1px;\n    border-radius: 8px; border: 2px solid var(--line); background: var(--surface-2);\n    display: grid; place-items: center; color: transparent;\n    transition: background .12s, border-color .12s;\n  }\n  .box svg { width: 16px; height: 16px; }\n  .box.on { background: var(--check); border-color: var(--check); color: #fff; }\n  .row.sub .box { width: 22px; height: 22px; border-radius: 6px; }\n  .main { flex: 1 1 auto; min-width: 0; }\n  .ttl { font-weight: 600; font-size: 16px; line-height: 1.3; }\n  .card.done .ttl { text-decoration: line-through; }\n  .pill {\n    display: inline-block; font-size: 11px; font-weight: 700; letter-spacing: .04em;\n    text-transform: uppercase; padding: 2px 7px; border-radius: 999px; margin-right: 6px;\n    color: var(--c); background: color-mix(in srgb, var(--c) 15%, transparent);\n    vertical-align: 2px;\n  }\n  .note {\n    color: var(--muted); font-size: 14px; margin-top: 4px;\n    display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;\n  }\n  .card.open .note { display: block; -webkit-line-clamp: unset; }\n  .note strong { color: var(--text); font-weight: 600; }\n  .note code, .ttl code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .92em; background: var(--surface-2); padding: 0 4px; border-radius: 4px; }\n  .note a { color: var(--accent); text-decoration: none; }\n  .subs { margin-top: 8px; display: none; flex-direction: column; gap: 8px; }\n  .card.open .subs { display: flex; }\n  .row.sub .txt { font-size: 14px; }\n  .row.sub.on .txt { text-decoration: line-through; color: var(--muted); }\n  .meta { font-size: 12px; color: var(--muted); margin-top: 6px; }\n\n  /* ---- FAB ---- */\n  .fab {\n    position: fixed; right: 20px; bottom: calc(var(--safe-bottom) + 20px);\n    width: 58px; height: 58px; border-radius: 18px;\n    background: var(--accent); color: var(--accent-ink);\n    display: grid; place-items: center; box-shadow: var(--shadow);\n    transition: transform .15s;\n    z-index: 5;\n  }\n  .fab:active { transform: scale(.94); }\n  .fab svg { width: 28px; height: 28px; }\n\n  /* ---- sheets ---- */\n  .scrim { position: fixed; inset: 0; background: rgba(0,0,0,.4); opacity: 0; pointer-events: none; transition: opacity .18s; z-index: 10; }\n  .scrim.show { opacity: 1; pointer-events: auto; }\n  .sheet {\n    position: fixed; left: 0; right: 0; bottom: 0; z-index: 11;\n    background: var(--surface); border-radius: 20px 20px 0 0;\n    padding: 12px 16px calc(var(--safe-bottom) + 16px);\n    transform: translateY(105%); transition: transform .22s cubic-bezier(.2,.8,.2,1);\n    max-height: 88dvh; overflow-y: auto;\n  }\n  .sheet.show { transform: none; }\n  .grab { width: 36px; height: 4px; border-radius: 2px; background: var(--line); margin: 0 auto 12px; }\n  .sheet h2 { font-size: 18px; margin: 0 0 12px; }\n  .field { margin-bottom: 14px; }\n  .field label { display: block; font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-bottom: 6px; }\n  .field input[type=text], .field textarea {\n    width: 100%; padding: 12px; border-radius: 12px; border: 1.5px solid var(--line);\n    background: var(--surface-2); outline: none;\n  }\n  .field input:focus, .field textarea:focus { border-color: var(--accent); }\n  .field textarea { min-height: 72px; resize: vertical; }\n  .seg { display: flex; flex-wrap: wrap; gap: 8px; }\n  .btn {\n    display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n    padding: 12px 16px; border-radius: 12px; font-weight: 600; background: var(--surface-2);\n    width: 100%;\n  }\n  .btn.primary { background: var(--accent); color: var(--accent-ink); }\n  .btn.quiet { background: transparent; color: var(--muted); }\n  .btn.danger { color: var(--danger); }\n  .btn:disabled { opacity: .5; }\n  .btnrow { display: flex; gap: 10px; margin-top: 6px; }\n  .help { font-size: 13px; color: var(--muted); margin: 0 0 12px; }\n  .help code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .92em; }\n\n  .toast {\n    position: fixed; left: 16px; right: 16px; bottom: calc(var(--safe-bottom) + 92px); z-index: 6;\n    background: var(--text); color: var(--bg); border-radius: 12px; padding: 12px 14px;\n    display: flex; align-items: center; justify-content: space-between; gap: 12px;\n    transform: translateY(20px); opacity: 0; pointer-events: none; transition: .18s;\n    font-size: 14px;\n  }\n  .toast.show { transform: none; opacity: 1; pointer-events: auto; }\n  .toast button { color: var(--accent); font-weight: 700; }\n  @media (prefers-color-scheme: dark) { :root:not([data-theme=\"light\"]) .toast button { color: #9ec0ff; } }\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"titlebar\">\n    <h1>Tasks</h1>\n    <div style=\"display:flex;align-items:center;gap:10px\">\n      <div class=\"status\" id=\"status\"><span class=\"dot\"></span><span id=\"statusText\">Not connected</span></div>\n      <button class=\"iconbtn\" id=\"btnRefresh\" aria-label=\"Refresh\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12a9 9 0 1 1-3-6.7\"/><path d=\"M21 3v6h-6\"/></svg>\n      </button>\n      <button class=\"iconbtn\" id=\"btnSettings\" aria-label=\"Settings\">\n        <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z\"/></svg>\n      </button>\n    </div>\n  </div>\n  <nav class=\"tabs\" id=\"tabs\"></nav>\n  <div class=\"tabs-rule\"></div>\n</header>\n\n<div class=\"chips\" id=\"chips\"></div>\n\n<main class=\"pages\" id=\"pages\"></main>\n\n<button class=\"fab\" id=\"fab\" aria-label=\"Add task\">\n  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>\n</button>\n\n<div class=\"toast\" id=\"toast\"><span id=\"toastText\"></span><button id=\"toastAction\" hidden>Undo</button></div>\n\n<div class=\"scrim\" id=\"scrim\"></div>\n\n<!-- Add sheet -->\n<section class=\"sheet\" id=\"addSheet\" aria-label=\"Add task\">\n  <div class=\"grab\"></div>\n  <h2>New task</h2>\n  <div class=\"field\">\n    <label for=\"addTitle\">Title</label>\n    <input type=\"text\" id=\"addTitle\" placeholder=\"What needs doing\" autocomplete=\"off\" enterkeyhint=\"done\">\n  </div>\n  <div class=\"field\">\n    <label>Tag</label>\n    <div class=\"seg\" id=\"addTags\"></div>\n  </div>\n  <div class=\"field\">\n    <label>Section</label>\n    <div class=\"seg\" id=\"addSections\"></div>\n  </div>\n  <div class=\"field\">\n    <label for=\"addNote\">Note (optional)</label>\n    <textarea id=\"addNote\" placeholder=\"Context, who, when\"></textarea>\n  </div>\n  <div class=\"btnrow\">\n    <button class=\"btn quiet\" id=\"addCancel\">Cancel</button>\n    <button class=\"btn primary\" id=\"addSave\">Add to top of section</button>\n  </div>\n</section>\n\n<!-- Settings sheet -->\n<section class=\"sheet\" id=\"settingsSheet\" aria-label=\"Settings\">\n  <div class=\"grab\"></div>\n  <h2>Dropbox</h2>\n  <p class=\"help\" id=\"settingsHelp\"></p>\n  <div class=\"field\" id=\"appKeyField\">\n    <label for=\"appKey\">App key</label>\n    <input type=\"text\" id=\"appKey\" placeholder=\"From dropbox.com/developers/apps\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n  </div>\n  <div class=\"field\">\n    <label for=\"filePath\">File path</label>\n    <input type=\"text\" id=\"filePath\" placeholder=\"/TASKS.md\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n  </div>\n  <div id=\"connectBlock\">\n    <div class=\"btnrow\">\n      <button class=\"btn primary\" id=\"btnConnect\">1. Open Dropbox to get a code</button>\n    </div>\n    <div class=\"field\" style=\"margin-top:14px\">\n      <label for=\"authCode\">2. Paste the code here</label>\n      <input type=\"text\" id=\"authCode\" placeholder=\"Code shown by Dropbox\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\">\n    </div>\n    <div class=\"btnrow\">\n      <button class=\"btn primary\" id=\"btnFinish\">Finish connecting</button>\n    </div>\n  </div>\n\n  <div class=\"btnrow\" style=\"margin-top:18px\">\n    <button class=\"btn danger\" id=\"btnSignOut\">Sign out</button>\n    <button class=\"btn quiet\" id=\"settingsClose\">Close</button>\n  </div>\n</section>\n\n<script>\n(() => {\n  'use strict';\n\n  // ---------- config / storage ----------\n  const LS = {\n    appKey: 'tasks.appKey',\n    path: 'tasks.path',\n    tokens: 'tasks.tokens',\n    verifier: 'tasks.pkceVerifier',\n    cache: 'tasks.cache',\n    filters: 'tasks.filters',\n    section: 'tasks.section',\n    tagOrder: 'tasks.tagOrder',\n    lastTag: 'tasks.lastTag',\n  };\n  // When a native host (the Scriptable script) embeds this page, it injects window.__host and\n  // window.__hostState before the page runs, and drains messages the page leaves in window.__outbox.\n  // The host persists tokens and cache on the device; localStorage is only a best-effort extra.\n  const host = window.__host ? {\n    send(msg) {\n      const w = window.__waiter;\n      if (w) { window.__waiter = null; w(msg); }\n      else (window.__outbox || (window.__outbox = [])).push(msg);\n    },\n  } : null;\n  const mem = new Map(Object.entries(window.__hostState || {}));\n  const store = {\n    get(k, fallback = null) {\n      if (mem.has(k)) return mem.get(k);\n      try { const v = localStorage.getItem(k); return v == null ? fallback : JSON.parse(v); } catch { return fallback; }\n    },\n    set(k, v) {\n      mem.set(k, v);\n      try { localStorage.setItem(k, JSON.stringify(v)); } catch {}\n      host?.send({ type: 'set', key: k, value: v });\n    },\n    del(k) {\n      mem.delete(k);\n      try { localStorage.removeItem(k); } catch {}\n      host?.send({ type: 'del', key: k });\n    },\n  };\n\n  // Tags come from the file itself: whatever appears as [Tag] at the start of items.\n  // Colors are assigned in order of first appearance and remembered so they stay stable.\n  const PALETTE = ['var(--tag-1)', 'var(--tag-2)', 'var(--tag-3)', 'var(--tag-4)', 'var(--tag-5)', 'var(--tag-6)'];\n  let tagOrder = store.get(LS.tagOrder, []);\n  function tagColor(t) {\n    const key = String(t).toLowerCase();\n    let i = tagOrder.indexOf(key);\n    if (i < 0) { tagOrder.push(key); store.set(LS.tagOrder, tagOrder); i = tagOrder.length - 1; }\n    return PALETTE[i % PALETTE.length];\n  }\n  function allTags() {\n    const counts = new Map();\n    (model?.sections || []).forEach(s => s.items.forEach(it => {\n      if (!it.tag) return;\n      const k = it.tag.toLowerCase();\n      counts.set(k, { name: counts.get(k)?.name || it.tag, n: (counts.get(k)?.n || 0) + 1 });\n    }));\n    return [...counts.values()].sort((a, b) => b.n - a.n).map(x => x.name);\n  }\n\n  const $ = id => document.getElementById(id);\n\n  // ---------- state ----------\n  let text = '';       // full file text\n  let rev = null;      // dropbox rev of `text`\n  let model = null;    // parsed sections\n  let activeFilters = new Set(store.get(LS.filters, []));\n  let currentSection = store.get(LS.section, 0);\n  let busy = false;\n\n  // ---------- markdown model ----------\n  // Lines are kept verbatim; every item remembers its line index so edits are surgical.\n  const RX_ITEM = /^(\\s*)- \\[( |x|X)\\] (.*)$/;\n  const RX_BOLD = /^\\*\\*\\[([^\\]]+)\\]\\s*(.*?)\\*\\*(?:\\s+-\\s+(.*))?$/;\n  const RX_STRIKE = /^~~\\[([^\\]]+)\\]\\s*(.*?)~~(?:\\s+-\\s+(.*))?$/;\n  const RX_PLAIN_TAG = /^\\[([^\\]]+)\\]\\s*(.*)$/;\n\n  function parse(src) {\n    const lines = src.split('\\n');\n    const sections = [];\n    let cur = null, item = null;\n    lines.forEach((line, i) => {\n      const h = /^##\\s+(.+?)\\s*$/.exec(line);\n      if (h) { cur = { name: h[1], line: i, items: [] }; sections.push(cur); item = null; return; }\n      if (!cur) return;\n      const m = RX_ITEM.exec(line);\n      if (!m) return;\n      const indent = m[1].length, done = m[2] !== ' ', body = m[3];\n      if (indent === 0) {\n        item = { line: i, done, tag: '', title: body, note: '', subs: [], raw: body };\n        let t = RX_BOLD.exec(body) || RX_STRIKE.exec(body);\n        if (t) { item.tag = t[1]; item.title = t[2]; item.note = t[3] || ''; }\n        else { const p = RX_PLAIN_TAG.exec(body); if (p) { item.tag = p[1]; item.title = p[2]; } }\n        cur.items.push(item);\n      } else if (item) {\n        item.subs.push({ line: i, done, text: body });\n      }\n    });\n    return { lines, sections };\n  }\n\n  // ---------- inline markdown ----------\n  const esc = s => s.replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n  function inline(s) {\n    let h = esc(s);\n    h = h.replace(/`([^`]+)`/g, '<code>$1</code>');\n    h = h.replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>');\n    h = h.replace(/~~(.+?)~~/g, '<s>$1</s>');\n    h = h.replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^)\\s]+)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>');\n    h = h.replace(/(^|[\\s(])(https?:\\/\\/[^\\s<)]+)/g, '$1<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$2</a>');\n    return h;\n  }\n\n  // ---------- rendering ----------\n  const CHECK = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7\"/></svg>';\n\n  function visible(item) {\n    if (activeFilters.size === 0) return true;\n    return activeFilters.has(item.tag.toLowerCase());\n  }\n\n  function render() {\n    if (!model) return;\n    const tabs = $('tabs'), pages = $('pages'), chips = $('chips');\n    const prevScroll = pages.scrollLeft;\n\n    // tabs\n    tabs.innerHTML = '';\n    model.sections.forEach((s, i) => {\n      const open = s.items.filter(it => !it.done && visible(it)).length;\n      const b = document.createElement('button');\n      b.className = 'tab' + (i === currentSection ? ' active' : '');\n      b.innerHTML = `${esc(s.name)}<span class=\"n\">${open}</span>`;\n      b.onclick = () => goTo(i);\n      tabs.appendChild(b);\n    });\n\n    // chips: every tag in the file, most used first\n    const tags = allTags();\n    chips.innerHTML = '';\n    const all = document.createElement('button');\n    all.className = 'chip' + (activeFilters.size === 0 ? ' on' : '');\n    all.textContent = 'All';\n    all.onclick = () => { activeFilters.clear(); persistFilters(); render(); };\n    chips.appendChild(all);\n    tags.forEach(t => {\n      const key = t.toLowerCase();\n      const count = (model.sections[currentSection]?.items || []).filter(it => it.tag.toLowerCase() === key && !it.done).length;\n      const c = document.createElement('button');\n      c.className = 'chip' + (activeFilters.has(key) ? ' on' : '');\n      c.style.setProperty('--c', tagColor(t));\n      c.innerHTML = `<span class=\"swatch\"></span>${esc(t)}<span class=\"n\">${count}</span>`;\n      c.onclick = () => { activeFilters.has(key) ? activeFilters.delete(key) : activeFilters.add(key); persistFilters(); render(); };\n      chips.appendChild(c);\n    });\n\n    // pages\n    const openCards = new Set([...pages.querySelectorAll('.card.open')].map(c => c.dataset.line));\n    pages.innerHTML = '';\n    model.sections.forEach((s, si) => {\n      const page = document.createElement('section');\n      page.className = 'page';\n      page.dataset.index = si;\n      const items = s.items.filter(visible);\n      if (items.length === 0) {\n        page.innerHTML = `<div class=\"empty\"><strong>Nothing here</strong>${activeFilters.size ? 'for this filter' : 'in ' + esc(s.name)}</div>`;\n      }\n      items.forEach(it => page.appendChild(card(it, openCards.has(String(it.line)))));\n      pages.appendChild(page);\n    });\n    pages.scrollLeft = prevScroll || currentSection * pages.clientWidth;\n    requestAnimationFrame(() => { pages.scrollLeft = currentSection * pages.clientWidth; });\n  }\n\n  function card(it, open) {\n    const el = document.createElement('article');\n    el.className = 'card' + (it.done ? ' done' : '') + (open ? ' open' : '');\n    el.dataset.line = it.line;\n    const subsOpen = it.subs.filter(s => !s.done).length;\n    el.innerHTML = `\n      <div class=\"row\">\n        <button class=\"box${it.done ? ' on' : ''}\" aria-label=\"Toggle\">${CHECK}</button>\n        <div class=\"main\">\n          <div class=\"ttl\">${it.tag ? `<span class=\"pill\" style=\"--c:${tagColor(it.tag)}\">${esc(it.tag)}</span>` : ''}${inline(it.title)}</div>\n          ${it.note ? `<div class=\"note\">${inline(it.note)}</div>` : ''}\n          ${it.subs.length ? `<div class=\"meta\">${subsOpen} of ${it.subs.length} subtasks open</div>` : ''}\n          <div class=\"subs\">${it.subs.map(s => `\n            <div class=\"row sub${s.done ? ' on' : ''}\" data-line=\"${s.line}\">\n              <button class=\"box${s.done ? ' on' : ''}\" aria-label=\"Toggle subtask\">${CHECK}</button>\n              <div class=\"txt\">${inline(s.text)}</div>\n            </div>`).join('')}</div>\n        </div>\n      </div>`;\n    el.querySelector('.row > .box').onclick = e => { e.stopPropagation(); toggleItem(it); };\n    el.querySelectorAll('.row.sub .box').forEach(b => {\n      b.onclick = e => { e.stopPropagation(); toggleSub(Number(b.closest('.row.sub').dataset.line)); };\n    });\n    el.onclick = e => { if (e.target.closest('a')) return; el.classList.toggle('open'); };\n    return el;\n  }\n\n  function goTo(i) {\n    currentSection = i;\n    store.set(LS.section, i);\n    const pages = $('pages');\n    pages.scrollTo({ left: i * pages.clientWidth, behavior: 'smooth' });\n    render();\n  }\n\n  // keep tab state in sync with swipes\n  let scrollTimer = null;\n  $('pages').addEventListener('scroll', () => {\n    clearTimeout(scrollTimer);\n    scrollTimer = setTimeout(() => {\n      const pages = $('pages');\n      const i = Math.round(pages.scrollLeft / pages.clientWidth);\n      if (i !== currentSection && model && i < model.sections.length) {\n        currentSection = i; store.set(LS.section, i);\n        // cheap update: tabs + chip counts only\n        [...$('tabs').children].forEach((t, k) => t.classList.toggle('active', k === i));\n        $('tabs').children[i]?.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });\n        renderChipCounts();\n      }\n    }, 80);\n  });\n  function renderChipCounts() {\n    const items = model.sections[currentSection]?.items || [];\n    [...$('chips').children].slice(1).forEach(c => {\n      const name = c.childNodes[1].textContent.toLowerCase();\n      c.querySelector('.n').textContent = items.filter(it => it.tag.toLowerCase() === name && !it.done).length;\n    });\n  }\n  function persistFilters() { store.set(LS.filters, [...activeFilters]); }\n\n  // ---------- edits ----------\n  function setMarker(line, done) {\n    return line.replace(/^(\\s*- )\\[( |x|X)\\]/, `$1[${done ? 'x' : ' '}]`);\n  }\n  function restyleTop(body, done) {\n    // open items are bold, done items are struck through: mirror the file's convention\n    const b = RX_BOLD.exec(body), s = RX_STRIKE.exec(body);\n    if (done && b) return `~~[${b[1]}] ${b[2]}~~` + (b[3] ? ` - ${b[3]}` : '');\n    if (!done && s) return `**[${s[1]}] ${s[2]}**` + (s[3] ? ` - ${s[3]}` : '');\n    return body;\n  }\n  function findSection(lines, name) {\n    return lines.findIndex(l => new RegExp(`^##\\\\s+${name.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}\\\\s*$`, 'i').test(l));\n  }\n\n  async function toggleItem(it) {\n    const lines = model.lines.slice();\n    const block = [it.line, ...it.subs.map(s => s.line)];\n    const end = block[block.length - 1];\n    const done = !it.done;\n    const m = RX_ITEM.exec(lines[it.line]);\n    lines[it.line] = setMarker(`${m[1]}- [ ] ${restyleTop(m[3], done)}`, done);\n    if (done) it.subs.forEach(s => { lines[s.line] = setMarker(lines[s.line], true); });\n\n    // move completed items to the top of Done; move un-done items out of Done to the top of Today\n    const fromName = model.sections[currentSection].name;\n    const targetName = done ? 'Done' : 'Today';\n    const targetIdx = findSection(lines, targetName);\n    if (targetIdx >= 0 && fromName.toLowerCase() !== targetName.toLowerCase()) {\n      const chunk = lines.splice(it.line, end - it.line + 1);\n      const insertAt = findSection(lines, targetName) + 1;\n      lines.splice(insertAt, 0, ...chunk);\n    }\n    await commit(lines.join('\\n'), done ? `Moved to ${targetName}` : `Reopened in ${targetName}`);\n  }\n\n  async function toggleSub(line) {\n    const lines = model.lines.slice();\n    const m = RX_ITEM.exec(lines[line]);\n    lines[line] = setMarker(lines[line], m[2] === ' ');\n    await commit(lines.join('\\n'), null);\n  }\n\n  function addTask({ title, tag, sectionName, note }) {\n    const lines = model.lines.slice();\n    let idx = findSection(lines, sectionName);\n    if (idx < 0) { lines.push('', `## ${sectionName}`); idx = lines.length - 1; }\n    const body = `**[${tag}] ${title}**` + (note ? ` - ${note}` : '');\n    lines.splice(idx + 1, 0, `- [ ] ${body}`);\n    return commit(lines.join('\\n'), 'Added');\n  }\n\n  let lastText = null;\n  async function commit(next, msg) {\n    if (busy) return;\n    const prev = text;\n    lastText = prev;\n    applyLocal(next);\n    if (msg) toast(msg, async () => { await commit(prev, null); });\n    try {\n      await upload(next);\n    } catch (e) {\n      if (e.status === 409) {\n        toast('File changed elsewhere, reloading');\n        await load(true);\n      } else {\n        setStatus('err', 'Save failed');\n        applyLocal(prev);\n        toast(e.message || 'Save failed');\n      }\n    }\n  }\n  function applyLocal(next) {\n    text = next;\n    model = parse(text);\n    store.set(LS.cache, { text, rev, at: Date.now() });\n    render();\n  }\n\n  // ---------- dropbox ----------\n  const tokens = () => store.get(LS.tokens);\n  const appKey = () => store.get(LS.appKey, '');\n  const filePath = () => store.get(LS.path, '/TASKS.md');\n\n  function b64url(buf) {\n    return btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '');\n  }\n  // Dropbox's no-redirect flow: Dropbox shows the user a code, the user pastes it here.\n  // No redirect URI, so this works from anywhere the page can run. PKCE still applies.\n  async function startAuth() {\n    const key = $('appKey').value.trim();\n    if (!key) { toast('Enter your Dropbox app key first'); return; }\n    if (!window.isSecureContext || !crypto.subtle) {\n      toast('Open this page over https or localhost to log in');\n      return;\n    }\n    store.set(LS.appKey, key);\n    store.set(LS.path, $('filePath').value.trim() || '/TASKS.md');\n    const rnd = crypto.getRandomValues(new Uint8Array(48));\n    const verifier = b64url(rnd);\n    const challenge = b64url(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier)));\n    store.set(LS.verifier, verifier);\n    const u = new URL('https://www.dropbox.com/oauth2/authorize');\n    u.search = new URLSearchParams({\n      client_id: key, response_type: 'code', code_challenge: challenge, code_challenge_method: 'S256',\n      token_access_type: 'offline',\n    });\n    window.open(u.toString(), '_blank', 'noopener');\n    setTimeout(() => $('authCode').focus(), 300);\n  }\n  async function finishAuth(code) {\n    const verifier = store.get(LS.verifier);\n    if (!verifier) throw new Error('Start with step 1 first');\n    const r = await fetch('https://api.dropboxapi.com/oauth2/token', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n      body: new URLSearchParams({ code, grant_type: 'authorization_code', code_verifier: verifier, client_id: appKey() }),\n    });\n    if (!r.ok) throw new Error('Token exchange failed: ' + await r.text());\n    saveTokens(await r.json());\n    store.del(LS.verifier);\n  }\n  function saveTokens(j) {\n    const t = tokens() || {};\n    store.set(LS.tokens, {\n      access: j.access_token,\n      refresh: j.refresh_token || t.refresh,\n      exp: Date.now() + (j.expires_in - 60) * 1000,\n    });\n  }\n  async function accessToken() {\n    const t = tokens();\n    if (!t) throw Object.assign(new Error('Not connected'), { noauth: true });\n    if (Date.now() < t.exp) return t.access;\n    const r = await fetch('https://api.dropboxapi.com/oauth2/token', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n      body: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: t.refresh, client_id: appKey() }),\n    });\n    if (!r.ok) { store.del(LS.tokens); throw Object.assign(new Error('Session expired, connect again'), { noauth: true }); }\n    saveTokens(await r.json());\n    return tokens().access;\n  }\n  async function download() {\n    const tok = await accessToken();\n    const r = await fetch('https://content.dropboxapi.com/2/files/download', {\n      method: 'POST',\n      headers: { Authorization: 'Bearer ' + tok, 'Dropbox-API-Arg': JSON.stringify({ path: filePath() }) },\n    });\n    if (!r.ok) throw Object.assign(new Error('Download failed: ' + await r.text()), { status: r.status });\n    const meta = r.headers.get('dropbox-api-result');\n    const body = await r.text();\n    let newRev = meta ? JSON.parse(meta).rev : null;\n    if (!newRev) {\n      const m = await fetch('https://api.dropboxapi.com/2/files/get_metadata', {\n        method: 'POST', headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' },\n        body: JSON.stringify({ path: filePath() }),\n      });\n      if (m.ok) newRev = (await m.json()).rev;\n    }\n    return { body, rev: newRev };\n  }\n  async function upload(content) {\n    busy = true; setStatus('busy', 'Saving');\n    try {\n      const tok = await accessToken();\n      const mode = rev ? { '.tag': 'update', update: rev } : 'overwrite';\n      const r = await fetch('https://content.dropboxapi.com/2/files/upload', {\n        method: 'POST',\n        headers: {\n          Authorization: 'Bearer ' + tok,\n          'Content-Type': 'application/octet-stream',\n          'Dropbox-API-Arg': JSON.stringify({ path: filePath(), mode, autorename: false, mute: true }),\n        },\n        body: new Blob([content], { type: 'text/plain' }),\n      });\n      if (!r.ok) throw Object.assign(new Error('Upload failed: ' + await r.text()), { status: r.status });\n      rev = (await r.json()).rev;\n      store.set(LS.cache, { text: content, rev, at: Date.now() });\n      setStatus('ok', 'Saved');\n    } finally { busy = false; }\n  }\n\n  async function load(quiet) {\n    if (!tokens()) { setStatus('', 'Not connected'); return; }\n    setStatus('busy', 'Syncing');\n    try {\n      const { body, rev: r } = await download();\n      rev = r;\n      text = body;\n      model = parse(text);\n      store.set(LS.cache, { text, rev, at: Date.now() });\n      render();\n      setStatus('ok', 'Up to date');\n    } catch (e) {\n      setStatus('err', e.noauth ? 'Not connected' : 'Offline');\n      if (!quiet) toast(e.message);\n    }\n  }\n\n  function setStatus(kind, msg) {\n    const s = $('status');\n    s.className = 'status ' + kind;\n    $('statusText').textContent = msg;\n  }\n\n  // ---------- sheets / toast ----------\n  let toastTimer = null;\n  function toast(msg, undo) {\n    $('toastText').textContent = msg;\n    const a = $('toastAction');\n    a.hidden = !undo;\n    a.onclick = () => { hideToast(); undo && undo(); };\n    $('toast').classList.add('show');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(hideToast, undo ? 5000 : 2800);\n  }\n  function hideToast() { $('toast').classList.remove('show'); }\n\n  function openSheet(id) { $('scrim').classList.add('show'); $(id).classList.add('show'); }\n  function closeSheets() { $('scrim').classList.remove('show'); document.querySelectorAll('.sheet').forEach(s => s.classList.remove('show')); }\n  $('scrim').onclick = closeSheets;\n\n  // add sheet\n  let addTag = null, addSection = null;\n  function openAdd() {\n    if (!model) { toast('Connect Dropbox first'); openSettings(); return; }\n    const secs = model.sections.map(s => s.name);\n    addSection = secs[currentSection] || secs[0];\n    const tags = allTags();\n    const single = [...activeFilters];\n    const pick = k => tags.find(t => t.toLowerCase() === k);\n    addTag = (single.length === 1 && pick(single[0])) || pick(store.get(LS.lastTag, '')) || tags[0] || 'Task';\n    const tagsEl = $('addTags'); tagsEl.innerHTML = '';\n    tags.forEach(t => {\n      const c = document.createElement('button');\n      c.className = 'chip' + (t === addTag ? ' on' : '');\n      c.style.setProperty('--c', tagColor(t));\n      c.innerHTML = `<span class=\"swatch\"></span>${t}`;\n      c.onclick = () => { addTag = t; [...tagsEl.children].forEach(x => x.classList.toggle('on', x === c)); };\n      tagsEl.appendChild(c);\n    });\n    const secEl = $('addSections'); secEl.innerHTML = '';\n    secs.filter(s => s.toLowerCase() !== 'done').forEach(s => {\n      const c = document.createElement('button');\n      c.className = 'chip' + (s === addSection ? ' on' : '');\n      c.textContent = s;\n      c.onclick = () => { addSection = s; [...secEl.children].forEach(x => x.classList.toggle('on', x === c)); };\n      secEl.appendChild(c);\n    });\n    $('addTitle').value = ''; $('addNote').value = '';\n    openSheet('addSheet');\n    setTimeout(() => $('addTitle').focus(), 250);\n  }\n  $('fab').onclick = openAdd;\n  $('addCancel').onclick = closeSheets;\n  $('addSave').onclick = async () => {\n    const title = $('addTitle').value.trim();\n    if (!title) { $('addTitle').focus(); return; }\n    closeSheets();\n    store.set(LS.lastTag, addTag.toLowerCase());\n    await addTask({ title, tag: addTag, sectionName: addSection, note: $('addNote').value.trim() });\n    const i = model.sections.findIndex(s => s.name === addSection);\n    if (i >= 0) goTo(i);\n  };\n  $('addTitle').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); $('addSave').click(); } });\n\n  // settings sheet\n  function openSettings() {\n    $('appKey').value = appKey();\n    $('filePath').value = filePath();\n    $('authCode').value = '';\n    const t = tokens();\n    if (host) {\n      $('settingsHelp').textContent = t\n        ? 'Connected. Reading and writing ' + filePath() + '.'\n        : 'Signed out. Close and reopen the app to log in to Dropbox again.';\n      $('appKeyField').hidden = true;\n      $('connectBlock').hidden = true;\n    } else {\n      $('settingsHelp').textContent = t\n        ? 'Connected. Reading and writing ' + filePath() + '.'\n        : 'Create an app at dropbox.com/developers/apps (Scoped access, permissions files.content.read and files.content.write) and paste its app key here. Step 1 opens Dropbox, which shows a code; paste it in step 2.';\n      $('appKeyField').hidden = !!t;\n      $('connectBlock').hidden = !!t;\n    }\n    $('btnSignOut').style.display = t ? '' : 'none';\n    openSheet('settingsSheet');\n  }\n  $('btnSettings').onclick = openSettings;\n  $('settingsClose').onclick = closeSheets;\n  $('btnConnect').onclick = startAuth;\n  $('btnFinish').onclick = async () => {\n    const code = $('authCode').value.trim();\n    if (!code) { $('authCode').focus(); return; }\n    try { await finishAuth(code); }\n    catch (e) { toast(e.message); return; }\n    closeSheets();\n    toast('Connected to Dropbox');\n    await load(false);\n  };\n  $('filePath').onchange = () => { store.set(LS.path, $('filePath').value.trim() || '/TASKS.md'); };\n  $('btnSignOut').onclick = () => {\n    store.del(LS.tokens); store.del(LS.cache);\n    host?.send({ type: 'signout' });\n    text = ''; model = null; rev = null; closeSheets();\n    $('pages').innerHTML = ''; $('tabs').innerHTML = ''; $('chips').innerHTML = '';\n    setStatus('', 'Not connected');\n    if (host) toast('Signed out. Reopen the app to log in again.');\n  };\n  $('btnRefresh').onclick = () => load(false);\n\n  // ---------- boot ----------\n  (async () => {\n    // show cached content immediately\n    const cache = store.get(LS.cache);\n    if (cache && cache.text) { text = cache.text; rev = cache.rev; model = parse(text); render(); setStatus('', 'Cached'); }\n\n    if (!tokens() && !cache) openSettings();\n    await load(true);\n\n    // refresh when coming back to the app\n    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible' && !busy) load(true); });\n    window.addEventListener('resize', () => { if (model) $('pages').scrollLeft = currentSection * $('pages').clientWidth; });\n  })();\n})();\n<\/script>\n</body>\n</html>\n";

// ---------------------------------------------------------------- storage
const fm = FileManager.local();
const STATE_FILE = fm.joinPath(fm.documentsDirectory(), 'tasks-state.json');
const TOKENS_KEY = 'tasks.tokens';
const KEYCHAIN_KEY = 'tasks.dropbox.tokens';

function readState() {
  try { return fm.fileExists(STATE_FILE) ? JSON.parse(fm.readString(STATE_FILE)) : {}; } catch { return {}; }
}
function writeState(s) { fm.writeString(STATE_FILE, JSON.stringify(s)); }
function readTokens() {
  try { return Keychain.contains(KEYCHAIN_KEY) ? JSON.parse(Keychain.get(KEYCHAIN_KEY)) : null; } catch { return null; }
}
function writeTokens(t) { if (t) Keychain.set(KEYCHAIN_KEY, JSON.stringify(t)); else if (Keychain.contains(KEYCHAIN_KEY)) Keychain.remove(KEYCHAIN_KEY); }

// ---------------------------------------------------------------- crypto (PKCE needs SHA-256; Scriptable has none built in)
function sha256Bytes(ascii) {
  const rotr = (v, n) => (v >>> n) | (v << (32 - n));
  const K = [], H = [];
  const isComposite = {};
  for (let c = 2, n = 0; n < 64; c++) {
    if (isComposite[c]) continue;
    for (let i = 0; i < 313; i += c) isComposite[i] = true;
    H[n] = (Math.pow(c, 0.5) * 4294967296) | 0;
    K[n++] = (Math.pow(c, 1 / 3) * 4294967296) | 0;
  }
  let hash = H.slice(0, 8);
  const bitLen = ascii.length * 8;
  ascii += '\x80';
  while (ascii.length % 64 - 56) ascii += '\x00';
  const words = [];
  for (let i = 0; i < ascii.length; i++) words[i >> 2] |= ascii.charCodeAt(i) << ((3 - i) % 4) * 8;
  words.push((bitLen / 4294967296) | 0, bitLen | 0);
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16), old = hash;
    hash = hash.slice(0, 8);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const a = hash[0], e = hash[4];
      const t1 = hash[7] + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + K[i]
        + (w[i] = i < 16 ? w[i] : (w[i - 16] + (rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10))) | 0);
      const t2 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(t1 + t2) | 0].concat(hash);
      hash[4] = (hash[4] + t1) | 0;
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + old[i]) | 0;
  }
  const out = [];
  for (let i = 0; i < 8; i++) for (let j = 3; j >= 0; j--) out.push((hash[i] >> (j * 8)) & 255);
  return out;
}
function b64url(bytes) {
  const T = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
    s += T[(n >> 18) & 63] + T[(n >> 12) & 63] + (i + 1 < bytes.length ? T[(n >> 6) & 63] : '') + (i + 2 < bytes.length ? T[n & 63] : '');
  }
  return s;
}

// ---------------------------------------------------------------- dropbox
function form(o) { return Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&'); }
async function postForm(url, body) {
  const r = new Request(url);
  r.method = 'POST';
  r.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
  r.body = form(body);
  const text = await r.loadString();
  const status = r.response?.statusCode ?? 200;
  if (status >= 300) throw new Error('Dropbox ' + status + ': ' + text);
  return JSON.parse(text);
}

async function ask(title, message, placeholder, def) {
  const a = new Alert();
  a.title = title; a.message = message;
  a.addTextField(placeholder, def || '');
  a.addAction('OK'); a.addCancelAction('Cancel');
  if (await a.present() < 0) return null;
  return a.textFieldValue(0).trim();
}

async function login(state) {
  let appKey = state['tasks.appKey'];
  if (!appKey) {
    appKey = await ask('Dropbox app key', 'From dropbox.com/developers/apps: your app, Settings tab, App key.', 'App key');
    if (!appKey) return null;
    state['tasks.appKey'] = appKey; writeState(state);
  }
  const verifier = (UUID.string() + UUID.string()).replace(/-/g, '');
  const challenge = b64url(sha256Bytes(verifier));
  const url = 'https://www.dropbox.com/oauth2/authorize?' + form({
    client_id: appKey, response_type: 'code', code_challenge: challenge,
    code_challenge_method: 'S256', token_access_type: 'offline',
  });
  await Safari.openInApp(url, false);          // returns when the sheet is dismissed
  let guess = '';
  try { const p = Pasteboard.paste(); if (p && /^[A-Za-z0-9_-]{20,}$/.test(p.trim())) guess = p.trim(); } catch {}
  const code = await ask('Paste the Dropbox code', 'Dropbox showed a code after you allowed access. Paste it here.', 'Code', guess);
  if (!code) return null;
  const j = await postForm('https://api.dropboxapi.com/oauth2/token', {
    code, grant_type: 'authorization_code', code_verifier: verifier, client_id: appKey,
  });
  const t = { access: j.access_token, refresh: j.refresh_token, exp: Date.now() + (j.expires_in - 60) * 1000 };
  writeTokens(t);
  return t;
}

// ---------------------------------------------------------------- widget: first section's open items from the cache
function widget(state) {
  const text = (state['tasks.cache'] && state['tasks.cache'].text) || '';
  const lines = text.split('\n');
  let section = '', items = [];
  for (const line of lines) {
    const h = /^##\s+(.+?)\s*$/.exec(line);
    if (h) { if (section) break; section = h[1]; continue; }
    if (!section) continue;
    const m = /^- \[ \] (?:\*\*)?(?:\[([^\]]+)\]\s*)?(.*?)(?:\*\*)?(?:\s+-\s+.*)?$/.exec(line);
    if (m) items.push({ tag: m[1] || '', title: m[2] });
  }
  const w = new ListWidget();
  w.url = URLScheme.forRunningScript();
  w.setPadding(14, 14, 14, 14);
  const head = w.addText((section || 'Tasks').toUpperCase());
  head.font = Font.semiboldSystemFont(11); head.textOpacity = 0.6;
  w.addSpacer(6);
  const max = config.widgetFamily === 'small' ? 3 : config.widgetFamily === 'large' ? 10 : 5;
  if (!items.length) { const t = w.addText(text ? 'Nothing open' : 'Open Tasks once to load'); t.font = Font.systemFont(13); }
  items.slice(0, max).forEach(it => {
    const t = w.addText((it.tag ? it.tag + ' · ' : '') + it.title);
    t.font = Font.systemFont(13); t.lineLimit = 1;
  });
  if (items.length > max) { w.addSpacer(4); const t = w.addText('+' + (items.length - max) + ' more'); t.font = Font.systemFont(11); t.textOpacity = 0.6; }
  Script.setWidget(w);
}

// ---------------------------------------------------------------- page host
const PUMP = '(function(){var o=window.__outbox||(window.__outbox=[]);if(o.length){completion(o.shift());}else{window.__waiter=completion;}})()';

async function pump(wv, state) {
  for (;;) {
    let msg;
    try { msg = await wv.evaluateJavaScript(PUMP, true); } catch { return; }
    if (!msg || typeof msg !== 'object') continue;
    if (msg.type === 'set') {
      if (msg.key === TOKENS_KEY) writeTokens(msg.value);
      else { state[msg.key] = msg.value; writeState(state); }
    } else if (msg.type === 'del') {
      if (msg.key === TOKENS_KEY) writeTokens(null);
      else { delete state[msg.key]; writeState(state); }
    } else if (msg.type === 'signout') {
      writeTokens(null);
    }
  }
}

async function main() {
  const state = readState();
  if (config.runsInWidget) { widget(state); return; }
  if (!config.runsInApp) {
    // Launched from Shortcuts, Siri or a share sheet: those contexts cannot present a web view,
    // so hand off to the Scriptable app, which reruns this script properly.
    Safari.open(URLScheme.forRunningScript());
    return;
  }

  let tokens = readTokens();
  if (!tokens) {
    tokens = await login(state);
    if (!tokens) return;
  }
  if (!state['tasks.path']) state['tasks.path'] = DEFAULT_PATH;

  const injected = Object.assign({}, state, { [TOKENS_KEY]: tokens });
  const boot = '<script>window.__host=1;window.__hostState=' + JSON.stringify(injected).replace(/</g, '\\u003c') + ';</script>';
  const html = HTML.replace('<head>', '<head>' + boot);

  const wv = new WebView();
  await wv.loadHTML(html, 'https://tasks.local/');
  pump(wv, state);                          // runs until the view is dismissed
  await wv.present(FULLSCREEN);
}

await main();
Script.complete();
